if (fs.existsSync(globalCssPath)) {
  const css = fs.readFileSync(globalCssPath, "utf8");
  if (!css.includes("desktop.css")) {
    const lines = css
      .trim()
      .split("\n")
      .filter((l) => !l.includes("desktop.css"));
    lines.push("@import './desktop.css';");
    write("src/styles/global.css", lines.join("\n") + "\n");
    console.log("  ↻ Added desktop.css import");
  }
}

/* ═══════════════════════════════════════════════════════════════
      14. FIX GitHub Actions deploy workflow
      ═══════════════════════════════════════════════════════════════ */

write(
  ".github/workflows/deploy.yml",
  `name: Deploy to GitHub Pages

   on:
     push:
       branches: [main]
     workflow_dispatch:

   permissions:
     contents: read
     pages: write
     id-token: write

   concurrency:
     group: "pages"
     cancel-in-progress: false

   jobs:
     build:
       runs-on: ubuntu-latest
       steps:
         - name: Checkout
           uses: actions/checkout@v4

         - name: Setup Node
           uses: actions/setup-node@v4
           with:
             node-version: '20'

         - name: Setup Pages
           uses: actions/configure-pages@v5

         - name: Create .env file
           run: |
             cat > .env << 'EOF'
             VITE_FIREBASE_API_KEY=\${{ secrets.VITE_FIREBASE_API_KEY }}
             VITE_FIREBASE_AUTH_DOMAIN=\${{ secrets.VITE_FIREBASE_AUTH_DOMAIN }}
             VITE_FIREBASE_PROJECT_ID=\${{ secrets.VITE_FIREBASE_PROJECT_ID }}
             VITE_FIREBASE_STORAGE_BUCKET=\${{ secrets.VITE_FIREBASE_STORAGE_BUCKET }}
             VITE_FIREBASE_MESSAGING_SENDER_ID=\${{ secrets.VITE_FIREBASE_MESSAGING_SENDER_ID }}
             VITE_FIREBASE_APP_ID=\${{ secrets.VITE_FIREBASE_APP_ID }}
             EOF

         - name: Install dependencies
           run: npm install --no-audit --no-fund --no-package-lock

         - name: Build
           run: npm run build

         - name: Verify build output
           run: |
             if [ ! -d "dist" ]; then
               echo "ERROR: dist folder was not created"
               exit 1
             fi
             ls -la dist/

         - name: Upload artifact
           uses: actions/upload-pages-artifact@v3
           with:
             path: './dist'

     deploy:
       needs: build
       runs-on: ubuntu-latest
       environment:
         name: github-pages
         url: \${{ steps.deployment.outputs.page_url }}
       steps:
         - name: Deploy to GitHub Pages
           id: deployment
           uses: actions/deploy-pages@v4
   `
);

