import { useMemo, useState } from 'react';
   import { Link } from 'react-router-dom';
   import { useCollection } from '@/lib/useRealtimeCollection';
   import { useAuth } from '@/lib/useAuth';
   import { teams } from '@/data/teams';
   import { REQUEST_TYPE_LABEL, REQUEST_STATUS_LABEL, PRIORITY_LABEL, formatDate, cx } from '@/lib/format';
   import { PageHeader } from '@/components/ui/PageHeader';
   import { SectionHeader } from '@/components/ui/SectionHeader';
   import { Badge } from '@/components/ui/Badge';
   import { EmptyState } from '@/components/ui/EmptyState';
   import { SkeletonList } from '@/components/ui/Loading';
   import type { RequestRecord, RequestStatus } from '@/types';

   const STATUSES: Array<RequestStatus | 'all'> = ['all', 'PENDING', 'IN_REVIEW', 'APPROVED', 'REJECTED'];
   const STATUS_TAB: Record<string, string> = { all: 'All', PENDING: 'Pending', IN_REVIEW: 'In Review', APPROVED: 'Approved', REJECTED: 'Rejected' };

   export function AdminRequestsPage() {
     const { user } = useAuth();
     const { data: requests, loading } = useCollection<RequestRecord>('requests');
     const [status, setStatus] = useState<RequestStatus | 'all'>('all');
     const filtered = useMemo(() => requests.filter((r) => status === 'all' || r.status === status).sort((a, b) => (a.submittedAt < b.submittedAt ? 1 : -1)), [requests, status]);
     return (
       <div className="admin-page">
         <PageHeader eyebrow="Admin" title="Requests" description="Manage all requests." />
         <div className="chips mb-4">{STATUSES.map((s) => <button key={s} type="button" className={cx('chip', status === s && 'is-active')} onClick={() => setStatus(s)}>{STATUS_TAB[s]}</button>)}</div>
         <SectionHeader eyebrow="List" title={'Requests (' + filtered.length + ')'} />
         {loading ? <SkeletonList count={5} /> : filtered.length === 0 ? <EmptyState title="No requests" message="No matching." /> : (
           <div className="stack">{filtered.map((r) => {
             const fromTeam = r.fromTeamId ? teams.find((t) => t.id === r.fromTeamId) : null;
             const toTeam = r.toTeamId ? teams.find((t) => t.id === r.toTeamId) : null;
             return (
               <div key={r.id} className="admin-request-card">
                 <div className="admin-request-card__head">
                   <div style={{ flex: 1, minWidth: 0 }}>
                     <div className="card__title">{r.title}</div>
                     <div className="card__meta">{r.requesterName} · {formatDate(r.submittedAt)}{fromTeam ? ' · from ' + fromTeam.name : ''}{toTeam ? ' · to ' + toTeam.name : ''}</div>
                   </div>
                   <div className="row" style={{ gap: 6 }}>
                     <Badge variant="neutral">{REQUEST_TYPE_LABEL[r.type]}</Badge>
                     <Badge variant={r.status === 'APPROVED' ? 'success' : r.status === 'REJECTED' ? 'danger' : r.status === 'IN_REVIEW' ? 'warning' : 'info'}>{REQUEST_STATUS_LABEL[r.status]}</Badge>
                     <Badge variant="neutral">{PRIORITY_LABEL[r.priority]}</Badge>
                   </div>
                 </div>
                 <div className="admin-request-card__actions">
                   <Link to={'/requests/' + r.id} className="btn btn--ghost btn--sm">Details</Link>
                 </div>
               </div>
             );
           })}</div>
         )}
       </div>
     );
   }
   
/* ===== END FILE: src/pages/admin/AdminRequestsPage.tsx ===== */

/* ===== FILE: src/pages/admin/AdminUsersPage.tsx ===== */
   import { useState, useMemo } from 'react';
   import { Link } from 'react-router-dom';
   import { useCollection } from '@/lib/useRealtimeCollection';
   import { useAuth } from '@/lib/useAuth';
   import { updateOne, removeOne } from '@/lib/db';
   import {
     adminCreateMember,
     adminResetUserPassword,
     adminUpdateUser,
     type UpdateUserInput,
   } from '@/lib/auth';
   import { logAudit } from '@/lib/audit';
   import { notifyUser } from '@/lib/notifications';
   import { teams } from '@/data/teams';
   import { ROLE_LABEL } from '@/lib/permissions';
   import { PageHeader } from '@/components/ui/PageHeader';
   import { SectionHeader } from '@/components/ui/SectionHeader';
   import { EmptyState } from '@/components/ui/EmptyState';
   import { SkeletonList } from '@/components/ui/Loading';
   import { Modal } from '@/components/ui/Modal';
   import { ConfirmDialog } from '@/components/ui/ConfirmDialog';
   import { FormField, TextInput, Select, MultiSelect, TextArea } from '@/components/ui/FormField';
   import { Badge } from '@/components/ui/Badge';
   import { Avatar } from '@/components/ui/Avatar';
   import { toast } from '@/components/ui/Toast';
   import type { AppUser, RoleId, TeamId, Member, Committee } from '@/types';

   const ROLE_OPTS: Array<{ value: RoleId; label: string }> = (
     Object.entries(ROLE_LABEL) as Array<[RoleId, string]>
   ).map(([value, label]) => ({ value, label }));

   const PASSWORD_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';

   function genPass(): string {
     let p = '';
     for (let i = 0; i < 10; i += 1) {
       p += PASSWORD_CHARS.charAt(Math.floor(Math.random() * PASSWORD_CHARS.length));
     }
     return p + '@1';
   }

   function copyToClipboard(text: string, label: string) {
     if (navigator.clipboard && navigator.clipboard.writeText) {
       navigator.clipboard.writeText(text)
         .then(() => toast.success(label + ' copied'))
         .catch(() => toast.error('Copy failed'));
     } else {
       const ta = document.createElement('textarea');
       ta.value = text;
       document.body.appendChild(ta);
       ta.select();
       try { document.execCommand('copy'); toast.success(label + ' copied'); }
       catch { toast.error('Copy failed'); }
       document.body.removeChild(ta);
     }
   }

   export function AdminUsersPage() {
     const { user: me } = useAuth();
     const { data: users, loading } = useCollection<AppUser>('users');
     const { data: liveMembers } = useCollection<Member>('members');
     const { data: liveCommittees } = useCollection<Committee>('committees');

     /* ─── Create form ─── */
     const [open, setOpen] = useState(false);
     const [busy, setBusy] = useState(false);
     const [email, setEmail] = useState('');
     const [password, setPassword] = useState(genPass());
     const [name, setName] = useState('');
     const [role, setRole] = useState<RoleId>('MEMBER');
     const [teamId, setTeamId] = useState<TeamId>('helpers');
     const [committeeIds, setCommitteeIds] = useState<string[]>([]);
     const [bio, setBio] = useState('');

     /* ─── Credentials modal ─── */
     const [created, setCreated] = useState<{
       email: string; password: string; name: string;
     } | null>(null);

     /* ─── Edit modal ─── */
     const [editUser, setEditUser] = useState<AppUser | null>(null);
     const [editForm, setEditForm] = useState<UpdateUserInput>({});
     const [editBusy, setEditBusy] = useState(false);

     /* ─── Password reset ─── */
     const [resetTarget, setResetTarget] = useState<AppUser | null>(null);
     const [resetBusy, setResetBusy] = useState(false);

     /* ─── Delete ─── */
     const [toDelete, setToDelete] = useState<AppUser | null>(null);
     const [deleteBusy, setDeleteBusy] = useState(false);

     /* ─── Search ─── */
     const [search, setSearch] = useState('');

     const filteredUsers = useMemo(() => {
       const q = search.trim().toLowerCase();
       if (!q) return users;
       return users.filter(
         (u) =>
           u.displayName.toLowerCase().includes(q) ||
           u.email.toLowerCase().includes(q),
       );
     }, [users, search]);

     const committees = useMemo(
       () => liveCommittees.map((c) => ({ id: c.id, nameAr: c.nameAr })),
       [liveCommittees],
     );

     const resetForm = () => {
       setEmail('');
       setPassword(genPass());
       setName('');
       setRole('MEMBER');
       setTeamId('helpers');
       setCommitteeIds([]);
       setBio('');
     };

     /* ═══════════════════════════════════════════════════════════
        CREATE
        ═══════════════════════════════════════════════════════════ */

     const handleCreate = async () => {
       if (!email.trim() || !name.trim()) {
         toast.error('Missing data', 'Email and name required');
         return;
       }
       const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
       if (!emailRe.test(email.trim())) {
         toast.error('Invalid email');
         return;
       }
       if (password.length < 6) {
         toast.error('Password too weak', 'Min 6 characters');
         return;
       }
       if (committeeIds.length === 0) {
         toast.error('Committee required', 'Select at least one');
         return;
       }

       setBusy(true);
       try {
         const result = await adminCreateMember(
           {
             email: email.trim(),
             temporaryPassword: password,
             name: name.trim(),
             role,
             teamIds: [teamId],
             committeeIds,
             bio: bio.trim() || undefined,
           },
           me?.uid ?? 'system',
         );

         try {
           await logAudit(me, 'CREATE_USER', 'User', result.uid, 'Created: ' + name);
         } catch { /* ignore */ }

         setCreated({ email: result.email, password, name: name.trim() });
         setOpen(false);
         resetForm();
         toast.success('User created', 'Appears in list instantly');
       } catch (err) {
         const msg = err instanceof Error ? err.message : 'Creation failed';
         toast.error('Failed', msg);
       } finally {
         setBusy(false);
       }
     };

     /* ═══════════════════════════════════════════════════════════
        EDIT — open modal with prefilled form
        ═══════════════════════════════════════════════════════════ */

     const openEdit = (u: AppUser) => {
       setEditUser(u);
       setEditForm({
         displayName: u.displayName,
         role: u.role,
         teamId: u.teamId ?? null,
         committeeIds: u.committeeIds ?? [],
       });
     };

     const saveEdit = async () => {
       if (!editUser) return;
       setEditBusy(true);
       try {
         await adminUpdateUser(editUser.uid, editForm);
         try {
           await logAudit(me, 'UPDATE_USER', 'User', editUser.uid, 'Updated profile');
         } catch { /* ignore */ }
         toast.success('User updated');
         setEditUser(null);
       } catch (err) {
         const msg = err instanceof Error ? err.message : 'Update failed';
         toast.error('Failed', msg);
       } finally {
         setEditBusy(false);
       }
     };

     /* ═══════════════════════════════════════════════════════════
        RESET PASSWORD — sends email
        ═══════════════════════════════════════════════════════════ */

     const confirmReset = async () => {
       if (!resetTarget) return;
       setResetBusy(true);
       try {
         await adminResetUserPassword(resetTarget.email);
         try {
           await logAudit(me, 'RESET_PASSWORD', 'User', resetTarget.uid, 'Password reset email sent');
         } catch { /* ignore */ }

         /* Also notify in-app */
         try {
           await notifyUser(
             resetTarget.uid,
             'Password reset requested',
             'A password reset email was sent to your inbox. Check your email.',
             'system',
             '/dashboard',
             'high',
             me?.displayName,
           );
         } catch { /* ignore */ }

         toast.success('Reset email sent', 'Check ' + resetTarget.email);
         setResetTarget(null);
       } catch (err) {
         const msg = err instanceof Error ? err.message : 'Reset failed';
         toast.error('Failed', msg);
       } finally {
         setResetBusy(false);
       }
     };

     /* ═══════════════════════════════════════════════════════════
        QUICK ACTIONS (inline)
        ═══════════════════════════════════════════════════════════ */

     const changeRole = async (uid: string, newRole: RoleId) => {
       try {
         await updateOne('users', uid, { role: newRole });
         try { await logAudit(me, 'CHANGE_ROLE', 'User', uid, 'Role → ' + newRole); } catch { /* ignore */ }
         toast.success('Role updated');
       } catch { toast.error('Failed'); }
     };

     const changeTeam = async (uid: string, newTeam: TeamId) => {
       try {
         await updateOne('users', uid, { teamId: newTeam });
         try { await logAudit(me, 'CHANGE_TEAM', 'User', uid, 'Team → ' + newTeam); } catch { /* ignore */ }
         toast.success('Team updated');
       } catch { toast.error('Failed'); }
     };

     const linkMember = async (uid: string, memberId: string) => {
       try {
         await updateOne('users', uid, { memberId: memberId || null });
         if (memberId) {
           await updateOne('members', memberId, { linkedUserId: uid });
         }
         try { await logAudit(me, 'LINK_MEMBER', 'User', uid, 'Member → ' + memberId); } catch { /* ignore */ }
         toast.success('Member linked');
       } catch { toast.error('Failed'); }
     };

     const sendWelcome = async (u: AppUser) => {
       try {
         await notifyUser(
           u.uid,
           'Welcome to sbapiaryy',
           'Your account is ready. Please change your password if you have not already.',
           'system',
           '/dashboard',
           'normal',
           me?.displayName,
         );
         toast.success('Notification sent to ' + u.displayName);
       } catch { toast.error('Failed to send'); }
     };

     /* ═══════════════════════════════════════════════════════════
        DELETE
        ═══════════════════════════════════════════════════════════ */

     const confirmDelete = async () => {
       if (!toDelete) return;
       setDeleteBusy(true);
       try {
         await removeOne('users', toDelete.uid);
         try {
           await logAudit(me, 'DELETE_USER', 'User', toDelete.uid, 'Deleted user doc');
         } catch { /* ignore */ }
         toast.success('User removed');
         setToDelete(null);
       } catch {
         toast.error('Failed to delete');
       } finally {
         setDeleteBusy(false);
       }
     };

     /* ═══════════════════════════════════════════════════════════
        RENDER
        ═══════════════════════════════════════════════════════════ */

     return (
       <div className="admin-page">
         <PageHeader
           eyebrow="Admin"
           title="Users"
           description="Create, edit, and manage accounts. Changes appear instantly."
         />

         <div className="toolbar">
           <input
             className="input"
             type="search"
             placeholder="Search by name or email..."
             value={search}
             onChange={(e) => setSearch(e.target.value)}
           />
           <button
             type="button"
             className="btn btn--primary"
             onClick={() => { resetForm(); setOpen(true); }}
           >
             + New User
           </button>
         </div>

         <SectionHeader
           eyebrow="List"
           title={'Users (' + filteredUsers.length + ')'}
         />

         {loading ? (
           <SkeletonList count={6} />
         ) : filteredUsers.length === 0 ? (
           <EmptyState
             title={search ? 'No matches' : 'No users yet'}
             message={search ? 'Try a different search.' : 'Create the first user.'}
           />
         ) : (
           <div className="stack">
             {filteredUsers.map((u) => {
               const linkedMember = liveMembers.find((m) => m.id === u.memberId);
               const userCommittees = liveCommittees.filter(
                 (c) => Array.isArray(u.committeeIds) && u.committeeIds.includes(c.id),
               );
               return (
                 <div key={u.uid} className="card no-click">
                   {/* ─── Header ─── */}
                   <div className="row row--between" style={{ gap: 12 }}>
                     <div style={{ display: 'flex', gap: 14, alignItems: 'center', flex: 1, minWidth: 0 }}>
                       <Avatar name={u.displayName} size={48} variant="navy" />
                       <div style={{ flex: 1, minWidth: 0 }}>
                         <div className="card__title" style={{ fontSize: '1rem' }}>
                           {u.displayName}
                           {u.mustChangePassword ? (
                             <Badge variant="warning" className="mt-2">New</Badge>
                           ) : null}
                         </div>
                         <div className="card__meta" dir="ltr" style={{ textAlign: 'start' }}>
                           {u.email}
                         </div>
                       </div>
                     </div>
                     <Badge variant="navy">{ROLE_LABEL[u.role]}</Badge>
                   </div>

                   {/* ─── Meta row ─── */}
                   <div className="row mt-3" style={{ gap: 8, flexWrap: 'wrap' }}>
                     {u.teamId ? (
                       <Badge variant="info">
                         {teams.find((t) => t.id === u.teamId)?.name ?? u.teamId}
                       </Badge>
                     ) : null}
                     {userCommittees.map((c) => (
                       <Badge key={c.id} variant="neutral">{c.nameAr}</Badge>
                     ))}
                     {linkedMember ? (
                       <Link to={'/members/' + linkedMember.id}>
                         <Badge variant="success">
                           Linked: {linkedMember.name}
                         </Badge>
                       </Link>
                     ) : (
                       <Badge variant="danger">Not linked to member</Badge>
                     )}
                   </div>

                   {/* ─── Inline controls ─── */}
                   <div className="row mt-4" style={{ gap: 10, flexWrap: 'wrap' }}>
                     <div style={{ flex: '1 1 180px', minWidth: 160 }}>
                       <div className="tiny muted" style={{ marginBottom: 4 }}>Role</div>
                       <select
                         className="input"
                         value={u.role}
                         onChange={(e) => changeRole(u.uid, e.target.value as RoleId)}
                       >
                         {ROLE_OPTS.map((o) => (
                           <option key={o.value} value={o.value}>{o.label}</option>
                         ))}
                       </select>
                     </div>

                     <div style={{ flex: '1 1 140px', minWidth: 130 }}>
                       <div className="tiny muted" style={{ marginBottom: 4 }}>Team</div>
                       <select
                         className="input"
                         value={u.teamId ?? ''}
                         onChange={(e) => changeTeam(u.uid, e.target.value as TeamId)}
                       >
                         <option value="">— None —</option>
                         {teams.map((t) => (
                           <option key={t.id} value={t.id}>{t.name}</option>
                         ))}
                       </select>
                     </div>

                     <div style={{ flex: '1 1 180px', minWidth: 160 }}>
                       <div className="tiny muted" style={{ marginBottom: 4 }}>Linked Member</div>
                       <select
                         className="input"
                         value={u.memberId ?? ''}
                         onChange={(e) => linkMember(u.uid, e.target.value)}
                       >
                         <option value="">— Not linked —</option>
                         {liveMembers.map((m) => (
                           <option key={m.id} value={m.id}>{m.name}</option>
                         ))}
                       </select>
                     </div>
                   </div>

                   {/* ─── Actions ─── */}
                   <div className="row mt-4" style={{ gap: 8, justifyContent: 'flex-end', paddingTop: 14, borderTop: '1px solid var(--c-line)' }}>
                     <button
                       type="button"
                       className="btn btn--ghost btn--sm"
                       onClick={() => openEdit(u)}
                     >
                       Edit Profile
                     </button>
                     <button
                       type="button"
                       className="btn btn--ghost btn--sm"
                       onClick={() => setResetTarget(u)}
                     >
                       Reset Password
                     </button>
                     <button
                       type="button"
                       className="btn btn--ghost btn--sm"
                       onClick={() => sendWelcome(u)}
                     >
                       Notify
                     </button>
                     <button
                       type="button"
                       className="btn btn--danger btn--sm"
                       onClick={() => setToDelete(u)}
                     >
                       Delete
                     </button>
                   </div>
                 </div>
               );
             })}
           </div>
         )}

         {/* ═══════════════════════════════════════════════════════
            CREATE MODAL
            ═══════════════════════════════════════════════════════ */}

         <Modal
           open={open}
           title="Create New User"
           onClose={() => setOpen(false)}
           wide
           footer={
             <>
               <button type="button" className="btn btn--ghost" onClick={() => setOpen(false)} disabled={busy}>
                 Cancel
               </button>
               <button type="button" className="btn btn--primary" onClick={handleCreate} disabled={busy}>
                 {busy ? 'Creating...' : 'Create Account'}
               </button>
             </>
           }
         >
           <p className="small muted" style={{ marginBottom: 18, lineHeight: 1.7 }}>
             The user will appear immediately. They can log in with this email
             and password, and will be asked to change their password on first login.
           </p>

           <FormField label="Full name" required>
             <TextInput value={name} onChange={setName} placeholder="e.g. Ahmed Mohamed" />
           </FormField>

           <FormField label="Email" required>
             <TextInput value={email} onChange={setEmail} type="email" placeholder="name@resala-stem.org" />
           </FormField>

           <FormField label="Temporary password" required hint="Min 6 characters">
             <div style={{ display: 'flex', gap: 8, alignItems: 'stretch' }}>
               <TextInput value={password} onChange={setPassword} type="text" />
               <button type="button" className="btn btn--ghost btn--sm" onClick={() => setPassword(genPass())}>
                 Generate
               </button>
               <button type="button" className="btn btn--ghost btn--sm" onClick={() => copyToClipboard(password, 'Password')}>
                 Copy
               </button>
             </div>
           </FormField>

           <FormField label="Role" required>
             <Select value={role} onChange={(v) => setRole(v as RoleId)} options={ROLE_OPTS} />
           </FormField>

           <FormField label="Team" required>
             <Select
               value={teamId}
               onChange={(v) => setTeamId(v as TeamId)}
               options={teams.map((t) => ({ value: t.id, label: t.name }))}
             />
           </FormField>

           <FormField
             label="Committees"
             required
             hint={committees.length === 0 ? 'Create a committee first from /admin/committees' : 'At least one required'}
           >
             <MultiSelect
               values={committeeIds}
               onChange={setCommitteeIds}
               options={committees.map((c) => ({ value: c.id, label: c.nameAr }))}
             />
           </FormField>

           <FormField label="Short bio">
             <TextInput value={bio} onChange={setBio} placeholder="Optional" />
           </FormField>
         </Modal>

         {/* ═══════════════════════════════════════════════════════
            CREDENTIALS MODAL
            ═══════════════════════════════════════════════════════ */}

         <Modal
           open={created !== null}
           title="✓ Account Created"
           onClose={() => setCreated(null)}
           footer={
             <>
               <button
                 type="button"
                 className="btn btn--ghost"
                 onClick={() =>
                   copyToClipboard(
                     'Name: ' + created?.name + '\nEmail: ' + created?.email + '\nPassword: ' + created?.password,
                     'All credentials',
                   )
                 }
               >
                 Copy All
               </button>
               <button type="button" className="btn btn--primary" onClick={() => setCreated(null)}>
                 Done
               </button>
             </>
           }
         >
           <p style={{ lineHeight: 1.8, marginBottom: 16 }}>
             Send these credentials to the member:
           </p>
           <div style={{
             background: 'var(--c-off-white)',
             border: '1px solid var(--c-line)',
             borderRadius: 'var(--radius-sm)',
             padding: 16,
             fontSize: '0.9rem',
             lineHeight: 2,
           }}>
             <div><strong>Name:</strong> {created?.name}</div>
             <div style={{ wordBreak: 'break-all', display: 'flex', justifyContent: 'space-between', gap: 8 }}>
               <span><strong>Email:</strong> <span dir="ltr">{created?.email}</span></span>
               <button type="button" className="btn btn--ghost btn--xs" onClick={() => copyToClipboard(created?.email || '', 'Email')}>Copy</button>
             </div>
             <div style={{ wordBreak: 'break-all', display: 'flex', justifyContent: 'space-between', gap: 8 }}>
               <span><strong>Password:</strong> <span dir="ltr" style={{ fontFamily: 'var(--font-en)' }}>{created?.password}</span></span>
               <button type="button" className="btn btn--ghost btn--xs" onClick={() => copyToClipboard(created?.password || '', 'Password')}>Copy</button>
             </div>
           </div>
           <p style={{ fontSize: '0.82rem', color: 'var(--c-ink-muted)', marginTop: 16, lineHeight: 1.7 }}>
             ⚠ Save these somewhere safe. Password will not be shown again.
           </p>
         </Modal>

         {/* ═══════════════════════════════════════════════════════
            EDIT MODAL
            ═══════════════════════════════════════════════════════ */}

         <Modal
           open={editUser !== null}
           title={'Edit: ' + (editUser?.displayName ?? '')}
           onClose={() => setEditUser(null)}
           wide
           footer={
             <>
               <button type="button" className="btn btn--ghost" onClick={() => setEditUser(null)} disabled={editBusy}>
                 Cancel
               </button>
               <button type="button" className="btn btn--primary" onClick={saveEdit} disabled={editBusy}>
                 {editBusy ? 'Saving...' : 'Save Changes'}
               </button>
             </>
           }
         >
           <FormField label="Display name" required>
             <TextInput
               value={editForm.displayName ?? ''}
               onChange={(v) => setEditForm({ ...editForm, displayName: v })}
             />
           </FormField>

           <FormField label="Role" required>
             <Select
               value={editForm.role ?? 'MEMBER'}
               onChange={(v) => setEditForm({ ...editForm, role: v as RoleId })}
               options={ROLE_OPTS}
             />
           </FormField>

           <FormField label="Team">
             <Select
               value={editForm.teamId ?? ''}
               onChange={(v) => setEditForm({ ...editForm, teamId: (v as TeamId) || null })}
               options={[{ value: '', label: '— None —' }, ...teams.map((t) => ({ value: t.id, label: t.name }))]}
             />
           </FormField>

           <FormField label="Committees">
             <MultiSelect
               values={editForm.committeeIds ?? []}
               onChange={(v) => setEditForm({ ...editForm, committeeIds: v })}
               options={committees.map((c) => ({ value: c.id, label: c.nameAr }))}
             />
           </FormField>

           <FormField label="Bio">
             <TextArea
               value={editForm.bio ?? ''}
               onChange={(v) => setEditForm({ ...editForm, bio: v })}
               rows={2}
             />
           </FormField>
         </Modal>

         {/* ═══════════════════════════════════════════════════════
            RESET PASSWORD MODAL
            ═══════════════════════════════════════════════════════ */}

         <Modal
           open={resetTarget !== null}
           title="Reset Password"
           onClose={() => setResetTarget(null)}
           footer={
             <>
               <button type="button" className="btn btn--ghost" onClick={() => setResetTarget(null)} disabled={resetBusy}>
                 Cancel
               </button>
               <button type="button" className="btn btn--primary" onClick={confirmReset} disabled={resetBusy}>
                 {resetBusy ? 'Sending...' : 'Send Reset Email'}
               </button>
             </>
           }
         >
           <p style={{ lineHeight: 1.8 }}>
             A password reset link will be sent to:
           </p>
           <div style={{
             background: 'var(--c-off-white)',
             borderRadius: 'var(--radius-sm)',
             padding: 14,
             marginTop: 10,
             fontFamily: 'var(--font-en)',
             direction: 'ltr',
             textAlign: 'start',
           }}>
             {resetTarget?.email}
           </div>
           <p style={{ fontSize: '0.85rem', color: 'var(--c-ink-muted)', marginTop: 14, lineHeight: 1.7 }}>
             The user will receive an email with a link to set a new password.
             Their current password will remain valid until they change it.
           </p>
         </Modal>

         {/* ═══════════════════════════════════════════════════════
            DELETE CONFIRM
            ═══════════════════════════════════════════════════════ */}

         <ConfirmDialog
           open={toDelete !== null}
           title="Delete User"
           message={'Remove "' + (toDelete?.displayName || '') + '" from Firestore? The Firebase Auth account must be deleted manually from Firebase Console if needed.'}
           confirmLabel="Delete"
           danger
           busy={deleteBusy}
           onConfirm={confirmDelete}
           onCancel={() => setToDelete(null)}
         />
       </div>
     );
   }
   
/* ===== END FILE: src/pages/admin/AdminUsersPage.tsx ===== */

/* ===== FILE: src/pages/admin/AdminWarningsPage.tsx ===== */
import { useState } from 'react';
   import { useCollection } from '@/lib/useRealtimeCollection';
   import { useAuth } from '@/lib/useAuth';
   import { createOne, updateOne, removeOne } from '@/lib/db';
   import { formatDate } from '@/lib/format';
   import { PageHeader } from '@/components/ui/PageHeader';
   import { SectionHeader } from '@/components/ui/SectionHeader';
   import { Badge } from '@/components/ui/Badge';
   import { EmptyState } from '@/components/ui/EmptyState';
   import { SkeletonList } from '@/components/ui/Loading';
   import { Modal } from '@/components/ui/Modal';
   import { ConfirmDialog } from '@/components/ui/ConfirmDialog';
   import { FormField, TextArea, DateInput, Select } from '@/components/ui/FormField';
   import { toast } from '@/components/ui/Toast';
   import type { WarningRecord, Member } from '@/types';

   const EMPTY: Omit<WarningRecord, 'id'> = { memberId: '', memberName: '', type: 'VERBAL', reason: '', severity: 'LOW', issuedByMemberId: '', issuedByName: '', issuedAt: new Date().toISOString().slice(0, 10), status: 'active', notes: '' };

   export function AdminWarningsPage() {
     const { user: me } = useAuth();
     const { data, loading } = useCollection<WarningRecord>('warnings');
     const { data: members } = useCollection<Member>('members');
     const [editing, setEditing] = useState<WarningRecord | null>(null);
     const [creating, setCreating] = useState(false);
     const [form, setForm] = useState<Omit<WarningRecord, 'id'>>(EMPTY);
     const [toDelete, setToDelete] = useState<WarningRecord | null>(null);
     const [busy, setBusy] = useState(false);
     const openCreate = () => { setForm({ ...EMPTY, issuedByMemberId: me?.memberId ?? '', issuedByName: me?.displayName ?? '' }); setCreating(true); setEditing(null); };
     const openEdit = (w: WarningRecord) => { setForm({ memberId: w.memberId, memberName: w.memberName || '', type: w.type, reason: w.reason, severity: w.severity, issuedByMemberId: w.issuedByMemberId || '', issuedByName: w.issuedByName || '', issuedAt: w.issuedAt, status: w.status, notes: w.notes || '' }); setEditing(w); setCreating(false); };
     const close = () => { setCreating(false); setEditing(null); };
     const save = async () => {
       if (!form.memberId || !form.reason.trim()) { toast.error('Member & reason required'); return; }
       setBusy(true);
       try {
         const member = members.find((m) => m.id === form.memberId);
         const payload = { ...form, memberName: member?.name ?? form.memberName };
         if (editing) { await updateOne('warnings', editing.id, payload); toast.success('Updated'); }
         else { const id = 'WARN-' + Date.now().toString(36).toUpperCase(); await createOne('warnings', { id, ...payload }); toast.success('Issued'); }
         close();
       } catch { toast.error('Failed'); }
       finally { setBusy(false); }
     };
     const del = async () => { if (!toDelete) return; setBusy(true); try { await removeOne('warnings', toDelete.id); toast.success('Deleted'); setToDelete(null); } catch { toast.error('Failed'); } finally { setBusy(false); } };
     return (
       <div className="admin-page">
         <PageHeader eyebrow="Admin" title="Warnings" description="Issue warnings." />
         <SectionHeader eyebrow="List" title={'Warnings (' + data.length + ')'} action={<button type="button" className="btn btn--primary btn--sm" onClick={openCreate}>+ New Warning</button>} />
         {loading ? <SkeletonList count={4} /> : data.length === 0 ? <EmptyState title="No warnings" message="No warnings issued." /> : (
           <div className="stack">{data.map((w) => (
             <div key={w.id} className="card no-click">
               <div className="row row--between"><div style={{ flex: 1, minWidth: 0 }}><div className="card__title">{w.memberName}</div><div className="card__meta">{w.reason}</div></div><Badge variant={w.status === 'active' ? 'danger' : 'success'} dot>{w.status === 'active' ? 'Active' : 'Resolved'}</Badge></div>
               <div className="row mt-3" style={{ gap: 6 }}><Badge variant="neutral">{w.type}</Badge><Badge variant={w.severity === 'HIGH' ? 'danger' : w.severity === 'MEDIUM' ? 'warning' : 'info'}>{w.severity}</Badge><span className="small muted">{formatDate(w.issuedAt)}</span></div>
               <div className="row mt-3" style={{ gap: 6, justifyContent: 'flex-end' }}>
                 <button type="button" className="btn btn--ghost btn--xs" onClick={() => openEdit(w)}>Edit</button>
                 <button type="button" className="btn btn--danger btn--xs" onClick={() => setToDelete(w)}>Delete</button>
               </div>
             </div>
           ))}</div>
         )}
         <Modal open={creating || editing !== null} title={editing ? 'Edit Warning' : 'New Warning'} onClose={close} wide
           footer={<><button type="button" className="btn btn--ghost" onClick={close}>Cancel</button><button type="button" className="btn btn--primary" onClick={save} disabled={busy}>{busy ? '...' : 'Save'}</button></>}>
           <FormField label="Member" required><Select value={form.memberId} onChange={(v) => { const m = members.find((x) => x.id === v); setForm({ ...form, memberId: v, memberName: m?.name ?? '' }); }} options={[{ value: '', label: '— Select —' }, ...members.map((m) => ({ value: m.id, label: m.name }))]} /></FormField>
           <FormField label="Type" required><Select value={form.type} onChange={(v) => setForm({ ...form, type: v as WarningRecord['type'] })} options={[{ value: 'VERBAL', label: 'Verbal' }, { value: 'WRITTEN', label: 'Written' }, { value: 'FINAL', label: 'Final' }]} /></FormField>
           <FormField label="Reason" required><TextArea value={form.reason} onChange={(v) => setForm({ ...form, reason: v })} rows={3} /></FormField>
           <FormField label="Severity" required><Select value={form.severity} onChange={(v) => setForm({ ...form, severity: v as WarningRecord['severity'] })} options={[{ value: 'LOW', label: 'Low' }, { value: 'MEDIUM', label: 'Medium' }, { value: 'HIGH', label: 'High' }]} /></FormField>
           <FormField label="Date" required><DateInput value={form.issuedAt} onChange={(v) => setForm({ ...form, issuedAt: v })} /></FormField>
           <FormField label="Status"><Select value={form.status} onChange={(v) => setForm({ ...form, status: v as 'active' | 'resolved' })} options={[{ value: 'active', label: 'Active' }, { value: 'resolved', label: 'Resolved' }]} /></FormField>
         </Modal>
         <ConfirmDialog open={toDelete !== null} title="Delete Warning" message="Confirm?" confirmLabel="Delete" danger busy={busy} onConfirm={del} onCancel={() => setToDelete(null)} />
       </div>
     );
   }
   
/* ===== END FILE: src/pages/admin/AdminWarningsPage.tsx ===== */

/* ===== FILE: src/pages/ApprovalsPage.tsx ===== */
import { Link } from 'react-router-dom';
   import { useCollection } from '@/lib/useRealtimeCollection';
   import { useAuth } from '@/lib/useAuth';
   import { canApproveStep, ROLE_LABEL } from '@/lib/permissions';
   import { PageHeader } from '@/components/ui/PageHeader';
   import { SectionHeader } from '@/components/ui/SectionHeader';
   import { Badge } from '@/components/ui/Badge';
   import { EmptyState } from '@/components/ui/EmptyState';
   import { SkeletonList } from '@/components/ui/Loading';
   import type { ApprovalStep, RequestRecord } from '@/types';

   export function ApprovalsPage() {
     const { user } = useAuth();
     const { data: approvals, loading } = useCollection<ApprovalStep>('approvals');
     const { data: requests } = useCollection<RequestRecord>('requests');
     if (!user) return null;
     const myPending = approvals.filter((a) => a.status === 'PENDING' && canApproveStep(user, a));
     return (
       <div className="container">
         <PageHeader eyebrow="Workflow" title="Approvals" description="Stages awaiting your decision." />
         <section className="section">
           <SectionHeader eyebrow="Pending" title={'Awaiting You (' + myPending.length + ')'} />
           {loading ? <SkeletonList count={3} /> : myPending.length === 0 ? <EmptyState title="All clear" message="Nothing pending for you." /> : (
             <div className="stack">{myPending.map((a) => {
               const req = requests.find((r) => r.id === a.requestId);
               return <Link key={a.id} to={'/requests/' + a.requestId} className="card"><div className="row row--between"><div style={{ flex: 1, minWidth: 0 }}><div className="card__title">{req?.title ?? a.requestId}</div><div className="card__meta">{ROLE_LABEL[a.requiredRole]} · Stage {a.order}</div></div><Badge variant="warning" dot>Awaiting</Badge></div></Link>;
             })}</div>
           )}
         </section>
       </div>
     );
   }
   
/* ===== END FILE: src/pages/ApprovalsPage.tsx ===== */

/* ===== FILE: src/pages/AuditPage.tsx ===== */
import { useCollection } from '@/lib/useRealtimeCollection';
   import { PageHeader } from '@/components/ui/PageHeader';
   import { EmptyState } from '@/components/ui/EmptyState';
   import { SkeletonList } from '@/components/ui/Loading';
   import { formatDateTime } from '@/lib/format';
   import type { AuditRecord } from '@/types';

   export function AuditPage() {
     const { data, loading } = useCollection<AuditRecord>('audit');
     const sorted = [...data].sort((a, b) => (a.date < b.date ? 1 : -1)).slice(0, 50);
     return (
       <div className="container">
         <PageHeader eyebrow="Log" title="Audit Log" description="All admin actions." />
         <section className="section">
           {loading ? <SkeletonList count={6} /> : sorted.length === 0 ? <EmptyState title="No events" message="No actions recorded yet." /> : (
             <div className="table-wrap"><table className="data">
               <thead><tr><th>Date</th><th>User</th><th>Action</th><th>Description</th></tr></thead>
               <tbody>{sorted.map((a) => <tr key={a.id}><td className="muted small nowrap">{formatDateTime(a.date)}</td><td style={{ fontWeight: 700 }}>{a.actorName}</td><td><span className="badge badge--neutral">{a.action}</span></td><td>{a.description}</td></tr>)}</tbody>
             </table></div>
           )}
         </section>
       </div>
     );
   }
   
